// Fail early on the one thing that silently ruins every email.
//
// Leads are added to an EXISTING Instantly campaign with the per-lead copy as
// custom variables {{ai_subject}} and {{ai_body}}. If that campaign's own
// sequence does not reference those variables, Instantly sends its static
// template to everyone and the personalised copy is never seen. That is an
// easy way to get "bad emails" with a flow that looks like it worked.
//
// This runs right after Config, before a single credit is spent. In dry-run
// mode it does nothing: the run produces the drafted emails as node output
// and touches Instantly not at all.
const cfg = $input.first().json;
if (cfg.dry_run) {
  console.log('Dry run: Instantly will not be called. Flip dry_run in Config to send.');
  return [{ json: cfg }];
}
const id = cfg.instantly_campaign_id;
if (!id || String(id).startsWith('PUT_')) {
  throw new Error('dry_run is off but instantly_campaign_id is not set. Put the campaign id from the Instantly URL in Config.');
}
if (!cfg.instantly_key || String(cfg.instantly_key).startsWith('PUT_')) {
  throw new Error('dry_run is off but instantly_key is not set.');
}
if (!this.helpers || !this.helpers.httpRequest) return [{ json: cfg }];

let camp;
try {
  camp = await this.helpers.httpRequest({ method: 'GET', json: true,
    url: 'https://api.instantly.ai/api/v2/campaigns/' + encodeURIComponent(id),
    headers: { Authorization: 'Bearer ' + cfg.instantly_key } });
} catch (e) {
  throw new Error('Could not read Instantly campaign ' + id + ': ' + e.message);
}
const text = JSON.stringify(camp.sequences || camp);
const uses = v => text.includes('{{' + v + '}}');
if (!uses('ai_body')) {
  throw new Error('Campaign "' + (camp.name || id) + '" does not use {{ai_body}} in its sequence, so every lead ' +
    'would get the campaign\'s static text instead of the email written for them. In Instantly, set the step ' +
    'subject to {{ai_subject}} and the body to {{ai_body}} (or {{ai_body_text}} for a plain-text campaign), ' +
    'then run again.');
}
console.log('Campaign "' + (camp.name || id) + '" uses {{ai_body}}' + (uses('ai_subject') ? ' and {{ai_subject}}' : ' (subject is the campaign\'s own)') +
  '; status ' + (camp.status ?? '?'));
if (!uses('ai_followup_1')) {
  console.log('NOTE: the campaign has no step using {{ai_followup_1}}. The flow writes two follow-ups per lead; ' +
    'add steps 2 and 3 (3 days apart) with body {{ai_followup_1}} and {{ai_followup_2}} — 42% of replies come from follow-ups and these cost nothing more to send.');
}
return [{ json: cfg }];

// Turn the ICP into Explee's own structured filter object.
//
// The previous flow sent the ICP as a prose `definition` with the geography
// mashed into the sentence, and Explee returned Microsoft for a French
// training-company ICP. `definition` is meant to be a company type ("real
// estate company"); countries and size are separate filters. nl-to-filters
// is Explee's free converter from prose to that object, and their own agent
// uses it — so use it, and fall back to prose only if it fails.
const cfg = $('Config').first().json;
const nl = $input.first().json || {};

// The HTTP node before this one continues on error, so a failure arrives
// here as { error } rather than stopping the flow.
const fromNl = !nl.error && (nl.filters || nl.company_filters ||
  (nl.definition || nl.countries || nl.industries ? nl : null));

let filters;
if (fromNl && typeof fromNl === 'object') {
  filters = { ...fromNl };
  for (const k of ['query', 'explanation', 'reasoning', 'people_filters']) delete filters[k];
  console.log('Filters from nl-to-filters: ' + JSON.stringify(filters).slice(0, 300));
} else {
  filters = { definition: cfg.definition };
  console.log('nl-to-filters gave nothing usable' + (nl.error ? ' (' + JSON.stringify(nl.error).slice(0, 120) + ')' : '') +
              ' — falling back to definition: ' + cfg.definition);
}
if (!filters.definition) filters.definition = cfg.definition;

// Criteria score companies 0-5 each. Explee 400s above three.
const criteria = (cfg.criteria || []).slice(0, 3);
if (criteria.length) filters.criteria = criteria;

return [{ json: { filters, page_size: cfg.page_size } }];

// From the company search to a ranked list of domains.
//
// Three things the earlier version did not do: read the criteria scores it
// paid for, check the country, and rank. It took whatever came back in
// whatever order and the resolution cap downstream then kept the first N.
const cfg = $('Config').first().json;

if (cfg.domains && cfg.domains.length) {
  return cfg.domains.map(domain => ({ json: { domain, source: 'manual' } }));
}

const j = $input.first().json || {};
const rows = j.companies || j.results || j.items || j.data || [];
const clean = d => String(d || '').trim().toLowerCase()
  .replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');

const allowed = (cfg.countries || []).map(c => String(c).toUpperCase());
// Country as an ISO code whatever form it arrives in. "Belgium" sliced to two
// letters is "BE" by luck; "Germany" would be "GE". Map names, keep codes.
const ISO = { france:'FR', belgium:'BE', belgique:'BE', luxembourg:'LU', switzerland:'CH', suisse:'CH', germany:'DE',
  allemagne:'DE', spain:'ES', espagne:'ES', italy:'IT', italie:'IT', netherlands:'NL', 'pays-bas':'NL', portugal:'PT',
  ireland:'IE', irlande:'IE', 'united kingdom':'GB', uk:'GB', 'united states':'US', usa:'US', canada:'CA',
  russia:'RU', china:'CN', india:'IN', poland:'PL', austria:'AT', sweden:'SE', denmark:'DK', norway:'NO' };
const iso = v => { const s = String(v || '').trim(); if (!s) return '';
  if (/^[A-Za-z]{2}$/.test(s)) return s.toUpperCase(); return ISO[s.toLowerCase()] || ''; };
const country = r => iso(r.country_code || r.country || r.company_country || r.geo);
const size = r => {
  const nums = String(r.employee_count || r.company_size || r.size || '').replace(/[,\s]/g, '').match(/\d+/g);
  return nums ? Math.max(...nums.map(Number)) : null;
};
// Explee attaches criteria scores 0-5 (with reasoning) when criteria are
// sent. Average them; a company with no scores is neutral, not zero.
const score = r => {
  const c = r.criteria || r.criteria_scores || r.scores;
  if (!Array.isArray(c) || !c.length) return null;
  const vals = c.map(v => Number(typeof v === 'object' ? (v.score ?? v.value) : v)).filter(n => !isNaN(n));
  return vals.length ? vals.reduce((a, b) => a + b, 0) / vals.length : null;
};

const dropped = { nodomain: 0, country: 0, size: 0, score: 0 };
const seen = new Set();
const kept = [];
for (const r of rows) {
  const domain = clean(r.domain || r.website || r.company_domain || r.companyWebsite || r.company_website || r.url);
  if (!domain || !domain.includes('.') || seen.has(domain)) { if (!seen.has(domain)) dropped.nodomain++; continue; }
  const cc = country(r);
  if (allowed.length && cc && !allowed.includes(cc)) { dropped.country++; continue; }
  const n = size(r);
  if (cfg.min_company_size && n !== null && n < cfg.min_company_size) { dropped.size++; continue; }
  const sc = score(r);
  if (cfg.min_criterion_score && sc !== null && sc < cfg.min_criterion_score) { dropped.score++; continue; }
  seen.add(domain);
  kept.push({ domain, company: r.name || r.company_name || '', country: cc, score: sc,
              what: r.description || r.company_description || '' });
}
kept.sort((a, b) => (b.score ?? 2.5) - (a.score ?? 2.5));

console.log('Domains: ' + kept.length + ' of ' + rows.length + ' companies kept ' + JSON.stringify(dropped) +
  (kept.length ? '; top: ' + kept.slice(0, 5).map(k => k.domain + (k.score != null ? '(' + k.score.toFixed(1) + ')' : '')).join(', ') : ''));

if (!kept.length) {
  throw new Error('No usable companies. ' + rows.length + ' returned, dropped ' + JSON.stringify(dropped) +
    '. Response keys: ' + Object.keys(j).join(', ') + '. First row: ' + JSON.stringify(rows[0] || j).slice(0, 400));
}
return kept.map(k => ({ json: k }));

// Who to write to at each company. Explee first, LinkFinder for the gaps.
//
// people-by-domains is a BULK endpoint (up to 1000 domains a request), so at
// scale this is a handful of calls, not one per company. Explee matches job
// titles semantically against the target roles and scores each person against
// the criteria; LinkFinder's seniority bucket covers domains Explee returns
// nobody for — a live call showed it returning a CFO for "director", so it is
// the fallback, not the lead.
const cfg = $('Config').first().json;
if (!this.helpers || !this.helpers.httpRequest) throw new Error('This n8n has no this.helpers.httpRequest in Code nodes.');
const http = opts => this.helpers.httpRequest(opts);
const sleep = ms => new Promise(r => setTimeout(r, ms));
const hasExplee = cfg.explee_key && !cfg.explee_key.startsWith('PUT_');
const hasLf = cfg.linkfinder_key && !cfg.linkfinder_key.startsWith('PUT_');
if (!hasExplee && !hasLf) throw new Error('No Explee or LinkFinder key in Config.');
const deadline = Date.now() + (Number(cfg.people_budget_seconds) || 240) * 1000;
const left = () => deadline - Date.now();

const companies = $input.all().map(i => i.json);
const meta = Object.fromEntries(companies.map(c => [c.domain, c]));
const clean = d => String(d || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/\/.*$/, '');
const out = [];
const covered = new Set();
const push = (p, via, domain) => {
  const m = meta[domain] || {};
  out.push({ ...p, source: via, company_domain: domain, _company: m.company, _company_score: m.score,
             _company_what: m.what, _company_country: m.country });
};

// 1. Explee, in chunks of domains.
if (hasExplee) {
  const CHUNK = Number(cfg.people_chunk) || 100;
  for (let i = 0; i < companies.length && left() > 30000; i += CHUNK) {
    const domains = companies.slice(i, i + CHUNK).map(c => c.domain);
    try {
      const x = await http({ method: 'POST', json: true, timeout: Math.min(120000, left() - 5000),
        url: 'https://api.explee.com/public/api/v1/search/people-by-domains',
        headers: { 'X-API-Key': cfg.explee_key },
        body: { domains, job_titles: (cfg.job_titles || ['Founder', 'Director']).slice(0, 20),
                criteria: (cfg.criteria || []).slice(0, 3), people_per_company: cfg.per_company } });
      const rows = (x && (x.people || x.results || x.items)) || [];
      const perDomain = {};
      for (const p of rows) {
        const d = clean(p.company_domain || p.domain || p.company_website) || domains.find(dm => String(p.company_url || '').includes(dm)) || '';
        if (!d) continue;
        (perDomain[d] = perDomain[d] || []).push(p);
      }
      for (const [d, ps] of Object.entries(perDomain)) {
        covered.add(d);
        for (const p of ps.slice(0, cfg.per_company)) push(p, 'explee', d);
      }
      console.log('Explee people: chunk ' + (i / CHUNK + 1) + ' -> ' + rows.length + ' people across ' + Object.keys(perDomain).length + ' of ' + domains.length + ' domains');
    } catch (e) { console.log('Explee people chunk ' + (i / CHUNK + 1) + ': ' + e.message); }
    await sleep(500);
  }
}

// 2. LinkFinder for the domains Explee left empty — capped, because each is
//    an async job of its own.
const gaps = companies.map(c => c.domain).filter(d => !covered.has(d));
const lfCap = Number(cfg.linkfinder_fallback_max) || 40;
if (hasLf && gaps.length) {
  const auth = { Authorization: 'Bearer ' + cfg.linkfinder_key };
  const LF = 'https://api.linkfinderai.com';
  let done = 0;
  for (const domain of gaps.slice(0, lfCap)) {
    if (left() < 30000) break;
    let r;
    try {
      r = await http({ method: 'POST', url: LF, headers: auth, json: true, timeout: 30000, body: {
        type: 'company_domain_to_employees', input_data: domain, seniority: cfg.seniority, employee_count: cfg.per_company } });
    } catch (e) { continue; }
    for (let n = 0; r && r.job_id && !r.result && n < 6 && left() > 25000; n++) {
      await sleep(8000);
      try { r = await http({ method: 'GET', headers: auth, json: true, url: r.poll_url || LF + '/status/' + r.job_id }); }
      catch (e) { r = null; }
    }
    const rows = (r && r.result) || [];
    for (const p of rows.slice(0, cfg.per_company)) push(p, 'linkfinder', domain);
    done++;
    await sleep(600);
  }
  console.log('LinkFinder fallback: ' + done + ' of ' + gaps.length + ' uncovered domains tried' + (gaps.length > lfCap ? ' (cap ' + lfCap + ')' : ''));
}

console.log('People: ' + out.length + ' across ' + companies.length + ' companies (' +
  out.filter(p => p.source === 'explee').length + ' explee, ' + out.filter(p => p.source === 'linkfinder').length + ' linkfinder)');
if (!out.length) throw new Error('Neither Explee nor LinkFinder found anyone at ' + companies.length + ' companies, e.g. ' + companies.slice(0, 8).map(c => c.domain).join(', '));
return [{ json: { people: out } }];

// The gate. Runs before anything that costs credits per person.
//
// Semantic title matching is how Explee finds people and why it over-returns;
// Explee's own AutoGTM log shows "Head of Sales Operations" bleeding into 32k
// generic "Head of Sales", fixed by requiring a literal on-target word in the
// real title. This does that, plus country, size, the criterion score, and a
// ranking so the cap downstream keeps the best rather than the first.
const cfg = $('Config').first().json;
const people = $input.first().json.people || [];
const norm = s => String(s || '').toLowerCase();

// Title words: configured, else derived from the target roles so the gate
// is on by default. Short function words are not evidence of anything.
const STOP = new Set(['de', 'du', 'des', 'la', 'le', 'les', 'et', 'of', 'the', 'and', 'in', 'at', 'for', 'en', 'a', 'à']);
const derived = (cfg.job_titles || []).flatMap(t => norm(t).split(/[\s\-\/,]+/))
  .filter(w => w.length > 2 && !STOP.has(w));
const want = ((cfg.title_keywords || []).length ? cfg.title_keywords : derived).map(norm).filter(Boolean);
const banned = (cfg.title_exclude || []).map(norm).filter(Boolean);
const allowed = (cfg.countries || []).map(c => String(c).toUpperCase());
const floor = Number(cfg.min_company_size) || 0;
const minScore = Number(cfg.min_criterion_score) || 0;

const titleOf = p => norm(p.job_title || p.jobTitle || p.title) + ' ' + norm(p.headline);
// Country as an ISO code whatever form it arrives in. "Belgium" sliced to two
// letters is "BE" by luck; "Germany" would be "GE". Map names, keep codes.
const ISO = { france:'FR', belgium:'BE', belgique:'BE', luxembourg:'LU', switzerland:'CH', suisse:'CH', germany:'DE',
  allemagne:'DE', spain:'ES', espagne:'ES', italy:'IT', italie:'IT', netherlands:'NL', 'pays-bas':'NL', portugal:'PT',
  ireland:'IE', irlande:'IE', 'united kingdom':'GB', uk:'GB', 'united states':'US', usa:'US', canada:'CA',
  russia:'RU', china:'CN', india:'IN', poland:'PL', austria:'AT', sweden:'SE', denmark:'DK', norway:'NO' };
const iso = v => { const s = String(v || '').trim(); if (!s) return '';
  if (/^[A-Za-z]{2}$/.test(s)) return s.toUpperCase(); return ISO[s.toLowerCase()] || ''; };
const countryOf = p => iso(p.geo || p.country_code || p.country || p._company_country);
const size = p => {
  const nums = String(p.company_size || p.companySize || '').replace(/[,\s]/g, '').match(/\d+/g);
  return nums ? Math.max(...nums.map(Number)) : null;
};
// Score against the FIRST criterion only. Summing buries a hard no under
// two soft yeses — their log calls that out too.
const score = p => {
  const c = p.criteria || p.criteria_scores || p.scores;
  if (!Array.isArray(c) || !c.length) return null;
  const v = c[0];
  const n = Number(typeof v === 'object' ? (v.score ?? v.value) : v);
  return isNaN(n) ? null : n;
};

const dropped = { title: 0, banned: 0, country: 0, size: 0, score: 0, noname: 0 };
const kept = [];
for (const p of people) {
  const name = p.full_name || p.name || [p.first_name || p.firstName, p.last_name || p.lastName].filter(Boolean).join(' ');
  if (!name) { dropped.noname++; continue; }
  const t = titleOf(p);
  if (want.length && !want.some(w => t.includes(w))) { dropped.title++; continue; }
  if (banned.some(b => t.includes(b))) { dropped.banned++; continue; }
  const cc = countryOf(p);
  if (allowed.length && cc && !allowed.includes(cc)) { dropped.country++; continue; }
  const n = size(p);
  if (floor && n !== null && n < floor) { dropped.size++; continue; }
  const sc = score(p);
  if (minScore && sc !== null && sc < minScore) { dropped.score++; continue; }
  kept.push({ ...p, _score: sc, _name: name });
}

// Best first: person score, then company score, then the ones Explee found.
kept.sort((a, b) =>
  ((b._score ?? 2.5) - (a._score ?? 2.5)) ||
  ((b._company_score ?? 2.5) - (a._company_score ?? 2.5)) ||
  ((a.source === 'explee' ? 0 : 1) - (b.source === 'explee' ? 0 : 1)));

const cap = Number(cfg.max_leads) || kept.length;
const final = kept.slice(0, cap);

console.log('Qualify: kept ' + final.length + ' of ' + people.length +
  ' (dropped ' + JSON.stringify(dropped) + (kept.length > cap ? ', ' + (kept.length - cap) + ' past max_leads' : '') +
  '); title words: ' + want.join('|'));

if (!final.length) {
  throw new Error('Nothing survived Qualify. ' + people.length + ' in, dropped ' + JSON.stringify(dropped) +
    '. Title words were [' + want.join(', ') + '], countries [' + allowed.join(', ') + ']. Titles seen: ' +
    [...new Set(people.map(p => p.job_title || p.jobTitle || p.title))].slice(0, 12).join(' | '));
}
return [{ json: { people: final } }];

// Start one Explee agent run per surviving company. Collection happens two
// nodes later, after a Wait — start-everything, wait, collect-everything is
// how a thousand async jobs fit inside n8n's per-node time limit without a
// polling loop. 1 credit per run. Fails soft: no key or no agents configured
// passes the people through untouched.
const cfg = $('Config').first().json;
const people = $input.first().json.people || [];
const passthrough = () => [{ json: { people, runs: [] } }];
const wanted = (cfg.signal_agents || []).filter(Boolean);
if (!wanted.length || !cfg.explee_key || cfg.explee_key.startsWith('PUT_') || !this.helpers || !this.helpers.httpRequest) return passthrough();

const http = opts => this.helpers.httpRequest(opts);
const API = 'https://api.explee.com/public/api/v1';
const headers = { 'X-API-Key': cfg.explee_key };
const deadline = Date.now() + (Number(cfg.signal_budget_seconds) || 200) * 1000;
const left = () => deadline - Date.now();

let agents;
try { agents = ((await http({ method: 'GET', url: API + '/agents', headers, json: true })) || {}).agents || []; }
catch (e) { console.log('Could not list Explee agents: ' + e.message); return passthrough(); }
const match = w => agents.find(a => String(a.id).toLowerCase() === String(w).toLowerCase() ||
  String(a.id).toLowerCase().endsWith('/' + String(w).toLowerCase()) || String(a.name || '').toLowerCase() === String(w).toLowerCase());
const chosen = wanted.map(w => [w, match(w)]);
const missing = chosen.filter(([, a]) => !a).map(([w]) => w);
if (missing.length) throw new Error('No Explee agent matches ' + missing.join(', ') + '. Available ids: ' + agents.map(a => a.id).join(', '));

const domains = [...new Set(people.map(p => String(p.company_domain || '').toLowerCase()).filter(Boolean))]
  .slice(0, Number(cfg.signal_max_companies) || 400);
const jobs = [];
for (const domain of domains) for (const [, agent] of chosen) jobs.push({ domain, agent: agent.id, key: agent.id.split('/').pop() });

const runs = [];
let next = 0, failed = 0;
async function lane() {
  while (next < jobs.length && left() > 10000) {
    const j = jobs[next++];
    try {
      const s = await http({ method: 'POST', url: API + '/agents/' + encodeURIComponent(j.agent) + '/runs', headers, json: true, body: { input_data: { domain: j.domain } } });
      if (s && s.run_id) runs.push({ ...j, run_id: s.run_id }); else failed++;
    } catch (e) { failed++; }
  }
}
await Promise.all(Array.from({ length: Math.min(8, jobs.length) }, lane));
console.log('Signals: started ' + runs.length + ' of ' + jobs.length + ' runs across ' + domains.length + ' companies (' + failed + ' failed to start, ~' + runs.length + ' credits)');
return [{ json: { people, runs } }];

// Collect the agent runs started two nodes ago. Each run is fetched once, in
// parallel lanes; one that is still not finished after the Wait is simply
// left without a signal. Results are compacted to what a writer can use.
const cfg = $('Config').first().json;
const { people = [], runs = [] } = $input.first().json || {};
if (!runs.length || !this.helpers || !this.helpers.httpRequest) return [{ json: { people } }];

const http = opts => this.helpers.httpRequest(opts);
const API = 'https://api.explee.com/public/api/v1';
const headers = { 'X-API-Key': cfg.explee_key };
const deadline = Date.now() + (Number(cfg.signal_budget_seconds) || 200) * 1000;
const left = () => deadline - Date.now();

const compact = (v, depth = 0) => {
  if (v == null) return undefined;
  if (typeof v === 'string') return v.length > 220 ? v.slice(0, 217) + '…' : v;
  if (typeof v !== 'object') return v;
  if (Array.isArray(v)) return v.slice(0, 3).map(x => compact(x, depth + 1)).filter(x => x !== undefined);
  if (depth >= 2) { const l = v.title || v.name || v.role || v.headline || v.summary; return typeof l === 'string' ? l.slice(0, 120) : undefined; }
  const o = {};
  for (const [k, val] of Object.entries(v)) {
    if (/url|trajectory|confidence_reasoning|raw|html/i.test(k)) continue;
    const c = compact(val, depth + 1);
    if (c !== undefined && c !== '' && !(Array.isArray(c) && !c.length)) o[k] = c;
  }
  return Object.keys(o).length ? o : undefined;
};

const byDomain = {};
let next = 0, got = 0, pending = 0;
async function lane() {
  while (next < runs.length && left() > 8000) {
    const r = runs[next++];
    try {
      const s = await http({ method: 'GET', headers, json: true, url: API + '/agents/runs/' + encodeURIComponent(r.run_id) });
      const status = String((s.meta && s.meta.status) || '').toLowerCase();
      const res = s.result && Object.keys(s.result).length ? compact(s.result) : null;
      if (res) { (byDomain[r.domain] = byDomain[r.domain] || {})[r.key] = res; got++; }
      else if (!['failed', 'error', 'cancelled', 'completed', 'done', 'success'].includes(status)) pending++;
    } catch (e) { /* no signal for this one */ }
  }
}
await Promise.all(Array.from({ length: Math.min(8, runs.length) }, lane));
console.log('Signals: ' + got + ' of ' + runs.length + ' runs returned something for ' + Object.keys(byDomain).length + ' companies' +
  (pending ? '; ' + pending + ' still running after the wait — raise the Wait if this is high' : ''));
return [{ json: { people: people.map(p => {
  const d = String(p.company_domain || '').toLowerCase();
  return byDomain[d] ? { ...p, signal: byDomain[d] } : p;
}) } }];

// One item per lead, in one shape, with a brief the writer can use.
//
// Explee answers in snake_case, LinkFinder in camelCase; the brief is the
// curated subset the writer is allowed to notice. The raw row also carries
// NACE sector scores, follower counts, photo urls and a company_geo that said
// CN for Microsoft — noise that dilutes the signal and invites invention.
const cfg = $('Config').first().json;
const j = $input.first().json || {};
let rows = j.people || j.results || j.items || j.contacts || [];
if (!rows.length) throw new Error('No people reached the writer. Upstream answered: ' + JSON.stringify(j).slice(0, 400));

// Only pay to reach people with a live trigger. Signal-based email runs
// 5-18% reply against 1-3% generic, and every lead past this point costs an
// address lookup and a model call — so a lead with nothing happening at their
// company is the most expensive kind to keep. On by default whenever trigger
// agents are configured; the drop is logged and, if it takes everyone, the
// error says so rather than sending nothing quietly.
if (cfg.require_signal && (cfg.signal_agents || []).length) {
  const withSignal = rows.filter(r => r.signal && Object.keys(r.signal).length);
  console.log('Signal gate: ' + withSignal.length + ' of ' + rows.length + ' leads have a live trigger; the rest are not emailed');
  if (!withSignal.length) {
    throw new Error('None of ' + rows.length + ' qualified leads has a trigger from ' + cfg.signal_agents.join(', ') +
      '. Either the agents returned nothing (check the Signals: collect log — was the Wait long enough?) or this segment is quiet. ' +
      'Set require_signal false in Config to email them anyway.');
  }
  rows = withSignal;
}

const pick = (...v) => v.find(x => x != null && x !== '') ?? '';
const NAME = { FR:'France', BE:'Belgium', LU:'Luxembourg', CH:'Switzerland', DE:'Germany', ES:'Spain', IT:'Italy',
  NL:'Netherlands', PT:'Portugal', IE:'Ireland', GB:'United Kingdom', US:'United States', CA:'Canada' };
const placeName = v => { const s = String(v || ''); return /^[A-Za-z]{2}$/.test(s) ? (NAME[s.toUpperCase()] || s) : s; };
return rows.map(c => {
  const first = pick(c.first_name, c.firstName);
  const last = pick(c.last_name, c.lastName);
  const full = pick(c._name, c.full_name, c.name, [first, last].filter(Boolean).join(' '));
  const lead = {
    full_name: full,
    first_name: first || String(full).split(' ')[0] || '',
    last_name: last || String(full).split(' ').slice(1).join(' '),
    email: pick(c.email),
    linkedin_url: pick(c.linkedin_url, c.linkedinUrl, c.linkedin),
    job_title: pick(c.job_title, c.jobTitle, c.title),
    company_name: pick(c.company_name, c.company, c._company),
    company_domain: pick(c.company_domain, c.companyWebsite, c.domain),
    location: placeName(pick(c.city, c.location, c.country, c.geo)),
    source: c.source || '',
    score: c._score ?? null,
  };
  const brief = Object.fromEntries(Object.entries({
    name: full,
    title: lead.job_title,
    headline: c.headline,
    company: lead.company_name,
    what_the_company_does: pick(c.company_description, c._company_what),
    industry: pick(c.company_industry, c.industry),
    company_size: pick(c.company_size, c.companySize),
    where: lead.location,
    // The buying trigger, already compacted by the signals node.
    whats_happening_there: c.signal,
  }).filter(([, v]) => v != null && v !== ''));
  return { json: { ...lead, brief, language: cfg.language || 'lead' } };
});

// Turn profiles into addresses. LinkFinder: 10 credits from a LinkedIn URL, 7
// from name + company, charged whether or not one comes back. Leads that
// already carry an email are never looked up.
//
// n8n kills a Code node at 300s (N8N_RUNNERS_TASK_TIMEOUT). A serial loop over
// 47 leads with a 1.1s spacer and an occasional 8s job poll blows that easily,
// so this works to a wall-clock budget with a few lookups in flight at once,
// and returns what it has when the budget runs out rather than dying with
// nothing. Raising the cap or the concurrency past the plan's requests/second
// is how you trade credits for 429s — the defaults sit under Starter's 5/s.
const cfg = $('Config').first().json;
const leads = $input.all().map(i => i.json);
const canHttp = !!(this.helpers && this.helpers.httpRequest);
const http = opts => this.helpers.httpRequest(opts);
const sendable = () => leads.filter(l => l.email).map(json => ({ json }));

if (!canHttp || !cfg.linkfinder_key || cfg.linkfinder_key.startsWith('PUT_')) {
  return sendable();
}

const auth = { Authorization: 'Bearer ' + cfg.linkfinder_key };
const API = 'https://api.linkfinderai.com';
const sleep = ms => new Promise(r => setTimeout(r, ms));
const deadline = Date.now() + (Number(cfg.linkfinder_budget_seconds) || 240) * 1000;
const left = () => deadline - Date.now();

// Only the leads that need a lookup and give us something to look up by.
const queue = [];
for (const lead of leads) {
  if (lead.email) continue;
  const op = lead.linkedin_url
    ? { type: 'linkedin_profile_to_email', input_data: lead.linkedin_url }
    : { type: 'lead_full_name_to_email', input_data:
        [lead.full_name || lead.name, lead.company_name || lead.company]
          .filter(Boolean).join(' ') };
  if (!op.input_data) continue;
  queue.push({ lead, op });
}
const budget = queue.splice(Number(cfg.linkfinder_max) || 0);
const skippedByCap = budget.length;

let found = 0, spent = 0, stopped = '';
let next = 0;

async function worker() {
  while (next < queue.length && !stopped) {
    if (left() < 15000) { stopped = 'out of time'; break; }
    const { lead, op } = queue[next++];
    spent += op.type === 'linkedin_profile_to_email' ? 10 : 7;
    let r;
    try {
      r = await http({ method: 'POST', url: API, headers: auth, body: op,
                       json: true, timeout: Math.min(30000, left()) });
    } catch (e) {
      // 402 out of credits, 401 bad key, 429 too fast: stop, do not hammer.
      stopped = e.message;
      break;
    }
    // Any endpoint can hand back a job instead of a result if it runs long.
    // Poll only while there is budget to spare for it.
    for (let n = 0; r && r.job_id && !r.result && n < 3 && left() > 20000; n++) {
      await sleep(5000);
      try {
        r = await http({ method: 'GET', headers: auth, json: true,
                         url: r.poll_url || API + '/status/' + r.job_id });
      } catch (e) { r = null; }
    }
    const res = r && r.result;
    const email = typeof res === 'string' ? res : (res && res.email) || '';
    if (email) { lead.email = email; found++; }
    await sleep(1100);          // per worker, so ~concurrency requests/second
  }
}

const lanes = Math.max(1, Math.min(Number(cfg.linkfinder_concurrency) || 4, 5));
await Promise.all(Array.from({ length: lanes }, worker));

const done = sendable();
console.log('LinkFinder: ' + found + ' emails, ~' + spent + ' credits, ' +
  done.length + ' of ' + leads.length + ' sendable' +
  (skippedByCap ? '; ' + skippedByCap + ' past linkfinder_max' : '') +
  (stopped ? '; stopped early: ' + stopped : ''));
return done;

// From the writer's answer to one Instantly lead.
//
// Pairs by the email the model was asked to echo back, not by position, so a
// skipped or reordered item cannot attach someone's copy to someone else.
// Finds the JSON by brace matching rather than expecting the whole reply to
// be JSON: an agent that adds a sentence first no longer loses the lead.
const cfg = $('Config').first().json;
// The resolved leads: the loop's "done" branch carries every batch's output.
// Fall back to the pre-resolution list if that reference is unavailable.
let leads = [];
try { leads = $('Loop Over Items').all(0).map(i => i.json); } catch (e) { leads = []; }
if (!leads.length) { try { leads = $('One item per lead').all().map(i => i.json); } catch (e) { leads = []; } }
const byEmail = Object.fromEntries(leads.filter(l => l.email).map(l => [String(l.email).toLowerCase(), l]));
const byName = Object.fromEntries(leads.map(l => [String(l.full_name + '|' + l.company_name).toLowerCase(), l]));

const extract = text => {
  if (typeof text !== 'string') return null;
  const s = text.indexOf('{');
  if (s < 0) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = s; i < text.length; i++) {
    const ch = text[i];
    if (inStr) { if (esc) esc = false; else if (ch === '\\') esc = true; else if (ch === '"') inStr = false; continue; }
    if (ch === '"') inStr = true;
    else if (ch === '{') depth++;
    else if (ch === '}') { depth--; if (!depth) { try { return JSON.parse(text.slice(s, i + 1)); } catch (e) { return null; } } }
  }
  return null;
};

const out = [], problems = [];
const replies = $input.all();
replies.forEach((item, i) => {
  const r = item.json || {};
  let text = r.output ?? r.text ?? r.choices?.[0]?.message?.content ?? '';
  if (typeof text !== 'string') text = JSON.stringify(text);
  const email = extract(text);
  if (!email || !email.subject || !email.body) { problems.push('item ' + i + ': no subject/body JSON in: ' + String(text).slice(0, 120)); return; }
  const key = String(email.email || '').toLowerCase();
  const lead = byEmail[key] || byName[String((email.name || '') + '|' + (email.company || '')).toLowerCase()] || leads[i];
  if (!lead || !lead.email) { problems.push('item ' + i + ': could not pair to a lead with an email (' + key + ')'); return; }
  const clean = t => String(t || '').replace(/\r\n/g, '\n').trim();
  const body = clean(email.body), f1 = clean(email.followup_1), f2 = clean(email.followup_2);
  const words = t => (t ? t.split(/\s+/).length : 0);
  if (words(body) > 95) problems.push(lead.email + ': ' + words(body) + ' words — over the 90-word ceiling, sent anyway');
  if (f1 && words(f1) > 60) problems.push(lead.email + ': follow-up 1 is ' + words(f1) + ' words, ceiling 55');
  if (f2 && words(f2) > 60) problems.push(lead.email + ': follow-up 2 is ' + words(f2) + ' words, ceiling 55');
  if (!f1 || !f2) problems.push(lead.email + ': missing a follow-up (steps 2-3 of the campaign will be empty for this lead)');
  out.push({ json: {
    email: lead.email,
    first_name: lead.first_name,
    last_name: lead.last_name,
    company_name: lead.company_name,
    website: lead.company_domain,
    custom_variables: {
      ai_subject: String(email.subject).trim(),
      ai_body: body.replace(/\n/g, '<br>'),     // for an HTML step
      ai_body_text: body,                        // for a plain-text step
      // Steps 2 and 3 of the campaign. 42% of replies come from follow-ups,
      // and these cost nothing extra to reach — the lead is already resolved.
      ai_followup_1: f1.replace(/\n/g, '<br>'), ai_followup_1_text: f1,
      ai_followup_2: f2.replace(/\n/g, '<br>'), ai_followup_2_text: f2,
    },
    // Kept out of what is sent, useful in the node output.
    _preview: '── ' + lead.full_name + ' <' + lead.email + '> · ' + lead.company_name + '\nSubject: ' + email.subject + '\n\n' + body +
      (f1 ? '\n\n── follow-up 1 (+3 days)\n' + f1 : '') + (f2 ? '\n\n── follow-up 2 (+3 days)\n' + f2 : ''),
  } });
});

if (problems.length) console.log('Build the lead: ' + problems.length + ' problem(s)\n' + problems.join('\n'));
console.log(out.length + ' emails ready' + (cfg.dry_run ? ' (dry run — read them in this node\'s output, nothing is sent)' : ' for campaign ' + cfg.instantly_campaign_id));
if (!out.length) throw new Error('Nothing to send — the writer produced no usable subject/body JSON. ' + problems.join(' | '));
return out;

// Add the leads to the Instantly campaign, 100 at a time.
//
// Only reached when dry_run is off (the Send? node). skip_if_in_workspace
// means a person already anywhere in your Instantly is never added twice.
const cfg = $('Config').first().json;
if (!this.helpers || !this.helpers.httpRequest) throw new Error('This n8n has no this.helpers.httpRequest in Code nodes.');
const leads = $input.all().map(i => { const { _preview, ...lead } = i.json; return lead; });
const CHUNK = 100;
let added = 0, skipped = 0;
const results = [];
for (let i = 0; i < leads.length; i += CHUNK) {
  const chunk = leads.slice(i, i + CHUNK);
  let r;
  try {
    r = await this.helpers.httpRequest({ method: 'POST', url: 'https://api.instantly.ai/api/v2/leads/list', json: true,
      headers: { Authorization: 'Bearer ' + cfg.instantly_key, 'Content-Type': 'application/json' },
      body: { campaign_id: cfg.instantly_campaign_id, skip_if_in_campaign: true, skip_if_in_workspace: true, leads: chunk } });
  } catch (e) {
    throw new Error('Instantly rejected chunk ' + (i / CHUNK + 1) + ' (' + chunk.length + ' leads) after ' + added + ' were added: ' + e.message);
  }
  const n = Number(r && (r.leads_uploaded ?? r.uploaded ?? r.added ?? r.total_sent ?? chunk.length));
  added += n; skipped += Math.max(0, chunk.length - n);
  results.push({ chunk: i / CHUNK + 1, sent: chunk.length, response: r });
}
console.log('Instantly: ' + added + ' leads added to campaign ' + cfg.instantly_campaign_id + (skipped ? ', ' + skipped + ' skipped as already present' : '') + '. The campaign stays as it was — arm it in Instantly.');
return [{ json: { added, skipped, campaign_id: cfg.instantly_campaign_id, chunks: results.length } }];
